import {modules,byId,countLessons} from '../data/modules.js';
import {questions,questionById} from '../data/questions.js';
import {flashcards} from '../data/flashcards.js';
import {water,indicator,indicatorNames,samples,buffer,salts,hydrolysis,solids,solubility,fmt,clamp} from './chemistry.js';
import {progress,save,update,award,replace,reset,level,today} from './store.js';
import {badges,refreshBadges} from './achievements.js';

const main=document.querySelector('#main');
const $=sel=>document.querySelector(sel);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const opt=(arr,value)=>arr.map(([v,label])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const progressM=m=>m.lessons.filter((_,i)=>progress.completedLessons.includes(`${m.id}/${i}`)).length;
const percent=(a,b)=>b?Math.round(100*a/b):0;
const doneSet=()=>new Set(progress.attempts.filter(a=>a.correct).map(a=>a.id));
const accuracy=topic=>{const attempts=progress.attempts.filter(a=>!topic||questionById(a.id)?.topic===topic);return {total:attempts.length,correct:attempts.filter(a=>a.correct).length,rate:percent(attempts.filter(a=>a.correct).length,attempts.length)}};
const uid=()=>new Date().toISOString();
const nameById=id=>byId(id)?.title||id;
const bar=(pct)=>`<div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${clamp(pct,0,100)}"><div class="progress-bar" style="width:${clamp(pct,0,100)}%"></div></div>`;
const button=(label,href,primary=true)=>`<a class="btn ${primary?'btn-primary':'btn-secondary'}" href="${href}">${label}</a>`;
let toastTimer;function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
let deck={topic:'all',onlyDue:false,index:0,flipped:false,order:null};
let practice={topic:'all',level:'all',mode:'livre',size:10,order:null,index:0,selected:null,feedback:null,answers:{},hint:false,sessionId:null};
let labId='agua';
function awardUpdate(code,points){if(award(code,points))toast(`✦ +${points} XP · Excelente!`);refreshBadges();updateHeader()}
function updateHeader(){document.documentElement.dataset.theme=progress.theme||'light';$('#sidebar-xp').textContent=`${progress.xp} XP`;$('#sidebar-level').textContent=`Nível ${level()}`;$('#theme-btn span').textContent=progress.theme==='dark'?'Tema claro':'Tema escuro';$('#theme-btn').firstChild.textContent=progress.theme==='dark'?'☀ ':'☾ ';const date=progress.lastStudy?new Date(progress.lastStudy).toLocaleDateString('pt-BR'):'—';$('#streak').textContent=`✧ Último estudo: ${date}`}
function setNavigation(root){document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===root));$('#breadcrumb').textContent=({inicio:'SEU LABORATÓRIO DE APRENDIZAGEM',aprender:'TRILHA DE APRENDIZAGEM',aula:'LIÇÃO INTERATIVA',laboratorio:'LABORATÓRIO VIRTUAL',cartoes:'REVISÃO INTELIGENTE',exercicios:'PRÁTICA E DESAFIOS',progresso:'ACOMPANHE SUA EVOLUÇÃO',intensivao:'PREPARAÇÃO PARA A PROVA',diagnostico:'AVALIAÇÃO INICIAL',referencias:'CIÊNCIA E METODOLOGIA'})[root]||'EQUILIBRA'}
function go(hash){location.hash=hash;if(location.hash.slice(1)===hash.replace('#',''))render()}
function lessonLink(){for(const m of modules)for(let i=0;i<m.lessons.length;i++)if(!progress.completedLessons.includes(`${m.id}/${i}`))return `#aula/${m.id}/${i}`;return '#intensivao'}
function heroArtwork(){return `<svg viewBox="0 0 330 310" fill="none" aria-hidden="true"><circle cx="158" cy="153" r="111" stroke="#ffffff70" stroke-width="1.5" stroke-dasharray="7 11"/><circle cx="158" cy="153" r="85" fill="#ffffff22"/><path d="M130 65h65m-50 0v73l-49 81c-10 18 4 36 24 36h89c21 0 33-18 23-36l-49-81V65" stroke="white" stroke-width="9" stroke-linejoin="round"/><path d="M115 197c22 6 76-7 101 4l17 29c3 9-6 15-17 15H120c-13 0-20-8-14-19l9-29Z" fill="#d1fff0cc"/><circle cx="155" cy="218" r="9" fill="#61acb4"/><circle cx="183" cy="232" r="5" fill="#7bc5ce"/><circle cx="175" cy="202" r="6" fill="#85d6c7"/><circle cx="77" cy="94" r="13" fill="#bcd8ff"/><circle cx="238" cy="96" r="11" fill="#ecdeff"/><circle cx="245" cy="185" r="6" fill="#d1f5cd"/><path d="M269 52l8 21 21 8-21 8-8 21-8-21-21-8 21-8 8-21Z" fill="#f7f6d2"/></svg>`}
function moduleCard(m){const p=percent(progressM(m),m.lessons.length);return `<article class="card module-card"><div class="round-icon" aria-hidden="true">${m.emoji}</div><div class="mini-meta">MÓDULO ${m.number} · ${m.difficulty}</div><h3>${esc(m.title)}</h3><p>${esc(m.subtitle)}</p><div class="module-bottom"><div class="score-row"><span>${progressM(m)}/${m.lessons.length} aulas</span><span>${p}%</span></div>${bar(p)}<a class="link" href="#aprender/${m.id}">${p===100?'Revisar módulo':'Explorar módulo'} →</a></div></article>`}
function home(){const completed=progress.completedLessons.length,learned=percent(completed,countLessons()),answered=doneSet().size;const next=lessonLink();return `<section class="hero"><div class="hero-copy"><span class="tag">✦ Aprender também é experimentar</span><h1>Química pode fazer<br>sentido. De verdade.</h1><p>Explore o equilíbrio iônico, faça descobertas no laboratório e evolua com cada desafio. Um conceito de cada vez.</p><div class="btn-row">${button('Começar a aprender →',next)}${button('Continuar meus estudos',`#aula/${progress.lastLesson||'fundamentos/0'}`,false)}</div></div><div class="hero-art">${heroArtwork()}</div></section>
<div class="grid g4" style="margin-top:21px"><div class="card"><span class="stat-title">Seu aprendizado</span><span class="stat-val">${learned}%</span><span class="stat-meta">de ${countLessons()} aulas</span>${bar(learned)}</div><div class="card"><span class="stat-title">Exercícios dominados</span><span class="stat-val">${answered}</span><span class="stat-meta">de 120 atividades</span></div><div class="card"><span class="stat-title">Pontos de experiência</span><span class="stat-val">${progress.xp}</span><span class="stat-meta">Nível ${level()}</span></div><div class="card"><span class="stat-title">Laboratórios desafiados</span><span class="stat-val">${progress.labChallenges.length}/5</span><span class="stat-meta">experimentos concluídos</span></div></div>
<div class="section-head"><div><h2>Sua jornada começa aqui</h2><p>Da base molecular às reações de precipitação.</p></div><a class="link" href="#aprender">Todos os módulos →</a></div><div class="grid g3">${modules.map(moduleCard).join('')}</div>
<div class="section-head"><div><h2>Aprenda do seu jeito</h2><p>Escolha por onde continuar seus estudos.</p></div></div><div class="grid g3"><div class="card mint"><div class="round-icon">⚗</div><h3>Aprenda fazendo</h3><p>Teste variáveis em cinco simuladores de laboratório.</p><a class="link" href="#laboratorio">Abrir laboratório →</a></div><div class="card lavender"><div class="round-icon">▣</div><h3>Memória em dia</h3><p>40 cartões e revisão baseada no seu desempenho.</p><a class="link" href="#cartoes">Revisar cartões →</a></div><div class="card sky"><div class="round-icon">✎</div><h3>Treino personalizado</h3><p>120 exercícios originais com resolução comentada.</p><a class="link" href="#exercicios">Praticar agora →</a></div></div>
<div class="section-head"><h2>Seu próximo passo</h2></div><div class="card"><div class="btn-row" style="align-items:center;justify-content:space-between"><div><h3 style="margin-bottom:6px">Continue de onde parou</h3><p class="muted" style="margin:0">${esc(progress.lastLesson?nameById(progress.lastLesson.split('/')[0]):'Fundamentos')} · Próxima sugestão baseada nas aulas pendentes</p></div>${button('Abrir próxima aula →',next)}</div><div class="divider"></div><div class="btn-row">${button('Fazer diagnóstico opcional','#diagnostico',false)}${button('Intensivão para provas','#intensivao',false)}</div></div>`}
function moduleIndex(id){const m=byId(id);if(!m)return `<p>Módulo não encontrado.</p>`;const done=progressM(m);return `<div class="page-intro"><span class="kicker">MÓDULO ${m.number} · ${esc(m.difficulty)}</span><h1>${m.emoji} ${esc(m.title)}</h1><p>${esc(m.subtitle)} · ${m.minutes} min de estudo estimado, sem limite de tempo.</p></div><div class="grid g2"><div class="card"><h3>Seu progresso</h3><strong>${done} de ${m.lessons.length} aulas finalizadas</strong>${bar(percent(done,m.lessons.length))}<p class="notice">Marque a aula como concluída depois de ler e praticar. Você pode revisitar cada conteúdo.</p></div><div class="card"><h3>Como estudar</h3><p class="muted">Leia a explicação, experimente «Ainda não entendi», acompanhe os exemplos, realize o laboratório e pratique com correção.</p>${button('Praticar o assunto',`#exercicios/${m.id}`,false)}</div></div><div class="section-head"><h2>Aulas do módulo</h2></div><div class="grid g2">${m.lessons.map((l,i)=>`<div class="card"><div class="mini-meta">LIÇÃO ${String(i+1).padStart(2,'0')} · ${progress.completedLessons.includes(m.id+'/'+i)?'✓ CONCLUÍDA':'PENDENTE'}</div><h3 style="margin-top:10px">${esc(l.title)}</h3><p class="muted">${esc(l.goal)}</p><a href="#aula/${m.id}/${i}" class="link">${progress.completedLessons.includes(m.id+'/'+i)?'Revisar aula':'Estudar aula'} →</a></div>`).join('')}</div>`}
function learn(){return `<div class="page-intro"><span class="kicker">SUA TRILHA</span><h1>Conhecimento, passo a passo.</h1><p>Comece com os fundamentos se estiver inseguro. Nenhum módulo fica bloqueado — você decide seu caminho.</p></div><div class="grid g3">${modules.map(moduleCard).join('')}</div><div class="card" style="margin-top:20px"><div class="btn-row"><div style="flex:1"><h3>Precisa revisar rápido?</h3><p class="muted">O Intensivão reúne as fórmulas, os erros mais comuns e um simulado.</p></div>${button('Abrir Intensivão','#intensivao')}</div></div>`}
function lesson(id,index){const m=byId(id),i=Number(index),l=m?.lessons?.[i];if(!l)return `<p>Aula não encontrada.</p>`;if(progress.lastLesson!==`${id}/${i}`){progress.lastLesson=`${id}/${i}`;save()};const isDone=progress.completedLessons.includes(`${id}/${i}`),prev=i>0?`#aula/${id}/${i-1}`:m.number>0?`#aprender/${modules[m.number-1].id}`:'#aprender',next=i<m.lessons.length-1?`#aula/${id}/${i+1}`:m.number<5?`#aprender/${modules[m.number+1].id}`:'#intensivao';return `<div class="page-intro"><a class="link" href="#aprender/${id}">← ${esc(m.title)}</a><span class="kicker" style="display:block;margin-top:13px">LIÇÃO ${i+1} DE ${m.lessons.length}</span><h1>${esc(l.title)}</h1><p>${esc(l.goal)}</p>${bar(percent(i+(isDone?1:0),m.lessons.length))}</div><div class="lesson-layout"><article class="card lesson-card"><div class="lesson-section"><span class="tag">01 · Antes de começar</span><h2>O que você vai descobrir?</h2><p>${esc(l.intro)}</p><div class="callout"><strong>Conhecimentos prévios:</strong> ${id==='fundamentos'?'Nenhum requisito; comece por aqui.':`Se precisar, <a href="#aprender/fundamentos">revise os fundamentos</a> (íons, pH, soluções e equilíbrio).`}</div></div><div class="lesson-section"><span class="tag">02 · Explicação</span><h3>Entenda o conceito</h3><div>${l.deep}</div><details class="details"><summary>✦ Ainda não entendi · Explique de outra forma</summary><p>${esc(l.alternative)}</p></details></div><div class="lesson-section"><span class="tag">03 · A fórmula sem mistério</span><h3>Leia a equação</h3><div class="formula">${esc(l.formula)}</div><details class="details"><summary>∑ Explique cada parte da fórmula</summary><p>${esc(l.why)}</p></details></div><div class="lesson-section"><span class="tag">04 · Exemplos resolvidos</span><h3>Do simples ao elaborado</h3>${l.examples.map((ex,i)=>`<div class="example"><strong>Exemplo ${i+1}</strong><p>${esc(ex)}</p></div>`).join('')}</div><div class="lesson-section"><span class="tag">05 · Experimentar e praticar</span><h3>Teste sua compreensão</h3><p>Aplique o que aprendeu com perguntas e observações visuais. Os exercícios exibem justificativas, inclusive dos erros.</p><div class="btn-row">${id==='fundamentos'?button('Praticar fundamentos','#exercicios/fundamentos',false):button('Explorar no laboratório',`#laboratorio/${id}`,false)}${button('Fazer exercícios',`#exercicios/${id}`,false)}</div></div><div class="lesson-section"><span class="tag">06 · Revisar e concluir</span><h3>Resumo do aprendizado</h3><p>${esc(l.goal)}</p><p class="muted">A revisão funciona melhor quando você consegue explicar o conceito com suas próprias palavras.</p><div class="btn-row"><button class="btn ${isDone?'btn-secondary':'btn-primary'}" data-action="lesson-done" data-id="${id}" data-index="${i}">${isDone?'✓ Aula concluída':'✓ Marcar aula como concluída'}</button><a class="btn btn-secondary" href="${next}">Próxima etapa →</a></div></div><div class="btn-row" style="margin-top:20px;justify-content:space-between"><a class="link" href="${prev}">← Voltar</a><a class="link" href="${next}">Continuar →</a></div></article><aside class="card lesson-side"><h3>Dentro deste módulo</h3><div class="links">${m.lessons.map((item,j)=>`<a class="link-item ${j===i?'current':''}" href="#aula/${id}/${j}">${progress.completedLessons.includes(`${id}/${j}`)?'✓':'○'} ${j+1}. ${esc(item.title)}</a>`).join('')}</div><div class="divider"></div><span class="tiny muted">${percent(progressM(m),m.lessons.length)}% do módulo concluído</span>${bar(percent(progressM(m),m.lessons.length))}</aside></div>`}
function labControls(id){switch(id){case 'agua':return `<div class="form-field"><label for="lab-temp">Temperatura</label><select class="input lab-input" id="lab-temp">${opt([[0,'0 °C'],[25,'25 °C'],[50,'50 °C']],25)}</select></div><div class="form-field"><label for="lab-h">[H₃O⁺] (mol/L)</label><input class="input lab-input" id="lab-h" type="number" min="0.000000000000001" max="10" step="any" value="0.0000001"></div>`;
case 'indicadores':return `<div class="form-field"><label for="lab-indicator">Indicador</label><select class="input lab-input" id="lab-indicator">${opt(Object.entries(indicatorNames),'btb')}</select></div><div class="form-field"><label for="lab-sample">Amostra</label><select class="input lab-input" id="lab-sample">${opt(Object.entries(samples).map(([id,s])=>[id,s.label]),'water')}</select></div><div class="form-field"><label for="lab-ph">pH estimado da amostra: <output id="ph-label">7,0</output></label><input class="input lab-input" id="lab-ph" type="range" min="0" max="14" step="0.1" value="7"></div>`;
case 'tampoes':return `<div class="form-field"><label for="lab-kind">Substância adicionada</label><select class="input lab-input" id="lab-kind">${opt([['acid','Ácido forte (H⁺)'],['base','Base forte (OH⁻)']],'acid')}</select></div><div class="form-field"><label for="lab-add">Adição em mol (a 1 L de solução): <output id="add-label">0,010</output></label><input class="input lab-input" id="lab-add" type="range" min="0" max="0.12" step="0.005" value="0.01"></div><div class="form-field"><label for="lab-acid">Quantidade inicial de HA (mol)</label><input class="input lab-input" type="number" id="lab-acid" value="0.1" min="0.001" max="1" step="0.01"></div><div class="form-field"><label for="lab-base">Quantidade inicial de A⁻ (mol)</label><input class="input lab-input" type="number" id="lab-base" value="0.1" min="0.001" max="1" step="0.01"></div><p class="notice">Modelo: tampão idealizado pKa 4,76, volume 1 L. Comparador: solução não tamponada inicialmente ajustada ao mesmo pH, em modelo de ácido/base forte.</p>`;
case 'hidrolise':return `<div class="form-field"><label for="lab-salt">Sal dissolvido</label><select class="input lab-input" id="lab-salt">${opt(Object.entries(salts).map(([k,s])=>[k,s.name]),'nacl')}</select></div><div class="form-field"><label for="lab-concentration">Concentração formal (mol/L)</label><select class="input lab-input" id="lab-concentration">${opt([[0.001,'0,001'],[0.01,'0,010'],[0.1,'0,100'],[1,'1,000']],0.1)}</select></div>`;
case 'kps':return `<div class="form-field"><label for="lab-solid">Sal pouco solúvel</label><select class="input lab-input" id="lab-solid">${opt(Object.entries(solids).map(([k,s])=>[k,s.name]),'agcl')}</select></div><div class="form-field"><label for="lab-c1">Concentração inicial do cátion (mol/L)</label><input class="input lab-input" id="lab-c1" type="number" min="0" max="2" step="any" value="0.0001"></div><div class="form-field"><label for="lab-c2">Concentração inicial do ânion (mol/L)</label><input class="input lab-input" id="lab-c2" type="number" min="0" max="2" step="any" value="0.0001"></div><p class="notice">Use, por exemplo, 0,0001 mol/L para ambos no AgCl para formar precipitado. Concentrações são valores após mistura e antes de precipitar.</p>`;default:return ''}}
function measure(label,value){return `<div class="measurement"><small>${label}</small><strong>${value}</strong></div>`}
function beaker(color='#6ec6c3',deposit=0,text='Solução aquosa'){return `<div class="lab-stage"><div class="beaker" aria-hidden="true"><div class="liquid" style="background:${color}"></div><div class="bubble"></div><div class="bubble b2"></div><div class="bubble b3"></div><div class="precip" style="height:${clamp(deposit,0,48)}%"></div></div><div class="stage-label">${text}</div></div>`}
function graphBars(data){return `<div class="bar-chart" role="img" aria-label="${esc(data.map(([k,v])=>k+': '+fmt(v)).join('; '))}">${data.map(([k,v])=>`<div class="bar-column"><span class="bar" style="height:${clamp(v/14*100,1,100)}%"></span><small>${esc(k)}</small></div>`).join('')}</div>`}
function labResult(id){let r;const get=s=>$(s)?.value;switch(id){case 'agua':r=water({h:+get('#lab-h'),temp:+get('#lab-temp')});if(r.error)break;return `${beaker(r.status==='Ácido'?'#ffc0a6':r.status==='Básico'?'#91a5ee':'#74c9c3',0,r.status+' · autoionização da água')}<div class="measurements">${measure('pH',fmt(r.ph))}${measure('pOH',fmt(r.poh))}${measure('Kw',r.kw.toExponential(2))}${measure('pH neutro nesta T',fmt(r.neutral))}${measure('[OH⁻] mol/L',r.oh.toExponential(2))}${measure('pKw',fmt(r.pkw))}</div><p><strong>Por quê?</strong> Kw=[H₃O⁺][OH⁻]. Portanto [OH⁻]=Kw/[H₃O⁺]. O valor neutro é pKw/2, não necessariamente 7.</p><p class="notice">Aproximação de concentrações em soluções ideais; atividades são relevantes em medidas precisas.</p>`;
case 'indicadores':r=indicator({indicator:get('#lab-indicator'),ph:+get('#lab-ph')});if(r.error)break;return `${beaker(r.color,0,`${esc(r.shade)} · ${esc(r.name)}`)}<div class="measurements">${measure('pH selecionado',fmt(r.ph,1))}${measure('Cor observada',esc(r.shade))}${measure('Faixa de viragem',esc(r.range))}${measure('Meio',esc(r.status))}</div><p><strong>Por quê?</strong> O equilíbrio entre formas do indicador muda com o pH, alterando a cor. A cor informa uma faixa, não um pH exato.</p><p class="notice">As cores são aproximações didáticas; sobretudo indicadores naturais dependem do preparo.</p>`;
case 'tampoes':r=buffer({acid:+get('#lab-acid'),base:+get('#lab-base'),kind:get('#lab-kind'),addition:+get('#lab-add')});if(r.error)break;return `${beaker(r.exhausted?'#d3afcb':'#70cbc0',0,r.exhausted?'Limite tamponante ultrapassado':'Sistema HA / A⁻')}<div class="measurements">${measure('pH inicial',fmt(r.initial))}${measure('pH com tampão',r.final===null?'Modelo inválido':fmt(r.final))}${measure('pH sem tampão',fmt(r.control))}${measure('A⁻ restante (mol)',fmt(r.b,3))}${measure('HA restante (mol)',fmt(r.a,3))}${measure('Adicionado (mol)',fmt(r.addition,3))}</div>${graphBars([['Inicial',r.initial],['Tampão',r.final??0],['Sem tampão',r.control]])}<p><strong>Interpretação:</strong> ${esc(r.explanation)}</p><p class="notice">Gráfico de pH, não de «proteção». Se o tampão esgotou, a barra de tampão não representa um pH calculado.</p>`;
case 'hidrolise':r=hydrolysis({salt:get('#lab-salt'),concentration:+get('#lab-concentration')});if(r.error)break;return `${beaker(r.ph<6.9?'#ecb6af':r.ph>7.1?'#a3acd9':'#8dcfbb',0,esc(r.name+' · '+r.trend))}<div class="measurements">${measure('pH aproximado',fmt(r.ph))}${measure('Tendência',esc(r.trend))}${measure('Concentração (mol/L)',fmt(r.concentration,3))}${measure('Temperatura','25 °C')}</div><p><strong>Dissociação:</strong> ${esc(r.name)} → ${esc(r.ions)}</p><p><strong>Hidrólise:</strong> ${esc(r.eq)}</p><p>${esc(r.explanation)}</p><p class="notice">${esc(r.caveat)}</p>`;
case 'kps':r=solubility({solid:get('#lab-solid'),c1:+get('#lab-c1'),c2:+get('#lab-c2')});if(r.error)break;return `${beaker(r.precip>0?'#a7c5ce':'#8dcece',r.precip>0?Math.min(48,4+Math.log10(1+r.precip*1e7)*8):0,esc(r.status))}<div class="measurements">${measure('Quociente Q',r.q.toExponential(2))}${measure('Kps (25 °C)',r.ksp.toExponential(2))}${measure('Q / Kps',fmt(r.ratio))}${measure('Precipitado (mol/L)',r.precip.toExponential(2))}${measure(r.ion1+' final',r.after1.toExponential(2))}${measure(r.ion2+' final',r.after2.toExponential(2))}</div><p><strong>Equação do quociente:</strong> ${esc(r.formula)}.</p><p>${esc(r.detail)}</p><p class="notice">${esc(r.caveat)}</p>`;
}return `<div class="feedback bad"><strong>Entrada inválida</strong>${esc(r?.error||'Revise os valores.')}</div>`}
const labNames={agua:'Equilíbrio da água',indicadores:'Indicadores coloridos',tampoes:'Defesa do pH',hidrolise:'Hidrólise de sais',kps:'Precipitação e Kps'};
const labChallenges={agua:'Ajuste pH ≈ 5,0 a 25 °C para vencer o desafio.',indicadores:'Use fenolftaleína em pH 11 para obter a cor rosa.',tampoes:'Adicione 0,01 mol de ácido ao tampão inicial (0,10 mol de HA e A⁻).',hidrolise:'Selecione NH₄Cl e identifique seu caráter ácido.',kps:'Selecione AgCl e ajuste os íons para conseguir Q > Kps.'};
function labPage(selected){labId=['agua','indicadores','tampoes','hidrolise','kps'].includes(selected)?selected:'agua';return `<div class="page-intro"><span class="kicker">EXPERIMENTAÇÃO VIRTUAL</span><h1>Laboratório de descobertas</h1><p>Mude variáveis, compare resultados calculados e descubra como o equilíbrio responde. São simulações, não instruções para experimentos caseiros.</p></div><div class="pill-list">${Object.keys(labNames).map(k=>`<a class="pill ${k===labId?'active':''}" href="#laboratorio/${k}">${esc(labNames[k])}</a>`).join('')}</div><div class="section-head"><div><h2>${esc(labNames[labId])}</h2><p>${labId==='tampoes'?'Compare uma solução tamponada com uma não tamponada.':'Explore a resposta do sistema aos controles.'}</p></div></div><div class="lab-grid"><div class="card"><span class="tag">01 · Seus controles</span>${labControls(labId)}<button class="btn btn-secondary full" data-action="lab-reset">↺ Reiniciar experimento</button><div class="divider"></div><h3>Desafio da bancada</h3><p class="muted">${esc(labChallenges[labId])}</p><button class="btn btn-primary full" data-action="lab-challenge">Verificar desafio ✓</button><div id="lab-challenge-msg" class="notice" style="margin-top:10px"></div></div><div class="card"><span class="tag">02 · Observação e cálculos</span><div id="lab-out" style="margin-top:15px">${labResult(labId)}</div></div></div><div class="card" style="margin-top:18px"><h3>O que observar?</h3><p>Compare o resultado com a expressão de equilíbrio e pergunte o que acontece se você inverter a perturbação. Valores próximos aos limites de um modelo exigem cautela.</p><a class="link" href="#aprender/${labId}">Revisar teoria →</a></div>`}
function checkLabChallenge(){const v=s=>$(s)?.value;switch(labId){case 'agua':return +v('#lab-temp')===25&&Math.abs(water({h:+v('#lab-h'),temp:25}).ph-5)<0.07;case 'indicadores':return v('#lab-indicator')==='phen'&&+v('#lab-ph')>=10.5;case 'tampoes':return v('#lab-kind')==='acid'&&Math.abs(+v('#lab-add')-.01)<.002&&Math.abs(+v('#lab-acid')-.1)<.002&&Math.abs(+v('#lab-base')-.1)<.002;case 'hidrolise':return v('#lab-salt')==='nh4cl';case 'kps':return solubility({solid:v('#lab-solid'),c1:+v('#lab-c1'),c2:+v('#lab-c2')}).ratio>1&&v('#lab-solid')==='agcl'}}
function getDeck(){let arr=flashcards.filter(c=>deck.topic==='all'||c.topic===deck.topic);if(deck.onlyDue)arr=arr.filter(c=>!progress.cards[c.id]||progress.cards[c.id].streak<3||progress.cards[c.id].nextDue<=today());if(deck.order)arr=[...arr].sort((a,b)=>deck.order.indexOf(a.id)-deck.order.indexOf(b.id));return arr}
function cardsPage(){const cards=getDeck();deck.index=clamp(deck.index,0,Math.max(0,cards.length-1));const card=cards[deck.index],reviewed=Object.keys(progress.cards).length,mastered=Object.values(progress.cards).filter(c=>c.streak>=3).length;return `<div class="page-intro"><span class="kicker">REVISÃO ESPAÇADA</span><h1>40 cartões. Muitas descobertas.</h1><p>Vire, responda mentalmente e classifique sua segurança. Os cartões difíceis retornam antes dos dominados.</p></div><div class="grid g3"><div class="card"><span class="stat-title">Cartões revisados</span><span class="stat-val">${reviewed}/40</span></div><div class="card"><span class="stat-title">Dominados (3 acertos seguidos)</span><span class="stat-val">${mastered}</span></div><div class="card"><span class="stat-title">Cartões disponíveis</span><span class="stat-val">${cards.length}</span></div></div><div class="filters"><select class="input" id="card-topic" style="max-width:270px"><option value="all">Todos os conteúdos</option>${opt(modules.slice(1).map(m=>[m.id,m.title]),deck.topic)}</select><label class="pill"><input type="checkbox" id="due-only" ${deck.onlyDue?'checked':''}> Revisão pendente/não dominados</label><button class="btn btn-secondary btn-sm" data-action="card-shuffle">⇄ Embaralhar</button></div>${card?`<p class="center muted">Cartão ${deck.index+1} de ${cards.length} · ${esc(nameById(card.topic))} · ${esc(card.difficulty)}</p><button class="flashcard ${deck.flipped?'flipped':''}" data-action="card-flip" aria-label="Virar cartão"><div class="flash-inner">${!deck.flipped?`<div><span class="flash-help">Pergunta · Clique para virar</span><h2 style="margin:20px 0">${esc(card.question)}</h2><span class="flash-help">↻ Revelar resposta</span></div>`:`<div><span class="flash-help">Resposta e explicação</span><h2 style="margin:20px 0">${esc(card.answer)}</h2><p>${esc(card.example)}</p></div>`}</div></button><div class="flash-actions"><button class="btn btn-secondary" data-action="card-prev" ${deck.index===0?'disabled':''}>← Anterior</button>${deck.flipped?`<button class="btn btn-secondary" data-action="card-rate" data-rating="err">Errei</button><button class="btn btn-secondary" data-action="card-rate" data-rating="doubt">Tenho dúvidas</button><button class="btn btn-primary" data-action="card-rate" data-rating="ok">Acertei ✓</button>`:`<button class="btn btn-primary" data-action="card-flip">Revelar resposta ↻</button>`}<button class="btn btn-secondary" data-action="card-next" ${deck.index===cards.length-1?'disabled':''}>Próximo →</button></div>`:`<div class="card center"><h3>Revisões em dia 🎉</h3><p>Não há cartões nessa seleção. Retorne para todos os cartões ou altere o filtro.</p><button class="btn btn-secondary" data-action="card-all">Mostrar todos</button></div>`}`}
function filteredQuestions(){let arr=questions.filter(q=>(practice.topic==='all'||q.topic===practice.topic)&&(practice.level==='all'||q.level===practice.level));if(practice.mode==='erros'){const missed=new Set(progress.attempts.filter(a=>!a.correct).map(a=>a.id));arr=arr.filter(q=>missed.has(q.id))}if(practice.mode==='diario'){const d=today().replace(/-/g,'');const offset=Number(d)%arr.length;arr=[...arr.slice(offset),...arr.slice(0,offset)].slice(0,10)}if(practice.mode==='simulado'||practice.mode==='diagnostico'){if(practice.order)return practice.order.map(questionById).filter(Boolean);const sorted=[...arr].sort((a,b)=>a.id.localeCompare(b.id));const chosen=[];const seed=Number(today().replace(/-/g,''));while(chosen.length<Math.min(practice.mode==='diagnostico'?5:practice.size,sorted.length)){let pos=(seed*17+chosen.length*37)%sorted.length;if(!chosen.includes(sorted[pos]))chosen.push(sorted[pos]);else {const free=sorted.find(q=>!chosen.includes(q));if(free)chosen.push(free);else break}}practice.order=chosen.map(q=>q.id);return chosen}return arr}
function questionInput(q){if(q.type==='numeric')return `<label class="form-field" for="number-answer"><span>Sua resposta numérica (use vírgula ou ponto)</span><input id="number-answer" class="input" inputmode="decimal" placeholder="Ex.: 1.34e-5" type="text"></label>`;
if(q.type==='fill')return `<label class="form-field" for="fill-answer"><span>Complete a resposta</span><input id="fill-answer" class="input" placeholder="Digite o termo" type="text"></label>`;
if(q.type==='match')return `<div class="choices">${q.pairs.map(([term],i)=>`<label class="form-field"><span>${esc(term)}</span><select class="input match-input" data-pair="${i}"><option value="">Selecione uma definição</option>${q.options.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select></label>`).join('')}</div>`;
return `<div class="choices">${q.options.map((c,i)=>`<button class="choice ${practice.selected===i?'selected':''}" data-action="q-choice" data-choice="${i}" type="button"><span class="letter">${String.fromCharCode(65+i)}</span>${esc(c)}</button>`).join('')}</div>`}
function qFeedback(q){const fb=practice.feedback;if(!fb)return '';return `<div class="feedback ${fb.correct?'ok':'bad'}"><strong>${fb.correct?'✓ Resposta correta!':'↻ Ainda não foi dessa vez'}</strong><p>${esc(q.why)}</p>${fb.correct?'<p>Seu progresso foi atualizado.</p>':'<p>Releia a explicação e tente novamente; você pode mudar sua resposta e verificar.</p>'}</div>`}
function questionPage(){const arr=filteredQuestions();practice.index=clamp(practice.index,0,Math.max(0,arr.length-1));const q=arr[practice.index];const attempts=accuracy();const isSim=['simulado','diagnostico'].includes(practice.mode);return `<div class="page-intro"><span class="kicker">PRÁTICA COM FEEDBACK</span><h1>Aprender também é tentar.</h1><p>120 exercícios originais, seis temas e diferentes formatos. Todo erro pode se transformar em uma nova descoberta.</p></div><div class="grid g3"><div class="card"><span class="stat-title">Exercícios disponíveis</span><span class="stat-val">120</span></div><div class="card"><span class="stat-title">Respostas registradas</span><span class="stat-val">${attempts.total}</span></div><div class="card"><span class="stat-title">Taxa por tentativa</span><span class="stat-val">${attempts.total?attempts.rate+'%':'—'}</span></div></div><div class="filters"><select class="input" id="q-mode" style="max-width:175px">${opt([['livre','Treino livre'],['erros','Revisão de erros'],['diario','Desafio diário'],['simulado','Simulado geral']],practice.mode==='diagnostico'?'livre':practice.mode)}</select><select class="input" id="q-topic" style="max-width:255px"><option value="all">Todos os assuntos</option>${opt(modules.map(m=>[m.id,m.title]),practice.topic)}</select><select class="input" id="q-level" style="max-width:160px">${opt([['all','Toda dificuldade'],['Fácil','Fácil'],['Médio','Médio'],['Difícil','Difícil']],practice.level)}</select>${practice.mode==='simulado'?`<select class="input" id="q-size" style="max-width:180px">${opt([[10,'10 questões'],[20,'20 questões'],[30,'30 questões']],practice.size)}</select>`:''}</div>${q?`<div class="question-box"><div class="question-controls"><span class="question-meta">${isSim?'SIMULADO · ':''}QUESTÃO ${practice.index+1} DE ${arr.length} · ${esc(nameById(q.topic))} · ${esc(q.level)}</span><span class="question-meta">${esc(q.type==='numeric'?'Cálculo':q.type==='boolean'?'Verdadeiro ou falso':q.type==='order'?'Sequência lógica':q.type==='graph'?'Leitura de gráfico':q.type==='match'?'Associação':q.type==='fill'?'Complete':'Múltipla escolha')}</span></div>${bar(percent(practice.index+1,arr.length))}<h3 style="margin-top:20px">${esc(q.text)}</h3>${q.chart?graphBars(q.chart):''}${questionInput(q)}<div class="btn-row"><button class="btn btn-primary" data-action="q-verify">Verificar resposta</button><button class="btn btn-subtle" data-action="q-hint">${practice.hint?'Ocultar dica':'Pedir uma dica'}</button></div>${practice.hint?`<p class="callout">💡 ${esc(q.hint)}</p>`:''}${qFeedback(q)}<div class="divider"></div><div class="question-controls"><button class="btn btn-secondary" data-action="q-prev" ${practice.index===0?'disabled':''}>← Anterior</button><span class="question-meta">${Object.keys(practice.answers).length} respondidas nesta sessão</span><button class="btn btn-secondary" data-action="q-next">${practice.index===arr.length-1?'Finalizar / Voltar ao início':'Próxima →'}</button></div></div>`:`<div class="card"><h3>Nenhuma questão neste filtro</h3><p class="muted">Tente outra combinação de tema, dificuldade ou modo.</p><button class="btn btn-secondary" data-action="q-reset-filters">Mostrar questões</button></div>`}<p class="notice">Em cálculos, aceitamos erro numérico pequeno previamente definido. Respostas incorretas também são armazenadas para oferecer revisão de erros.</p>`}
function statsView(){const complete=progress.completedLessons.length,acc=accuracy(),cardsReviewed=Object.keys(progress.cards).length,completedModules=modules.filter(m=>progressM(m)===m.lessons.length).length;return `<div class="page-intro"><span class="kicker">SEU PAINEL PESSOAL</span><h1>Veja o quanto você evoluiu.</h1><p>Os números abaixo são calculados a partir de suas atividades reais neste navegador. Sem progresso fictício.</p></div><div class="grid g4"><div class="card">${measure('Aulas concluídas',`${complete}/${countLessons()}`)}${bar(percent(complete,countLessons()))}</div><div class="card">${measure('Módulos finalizados',`${completedModules}/6`)}</div><div class="card">${measure('Respostas registradas',acc.total)}</div><div class="card">${measure('Taxa de acerto por tentativa',acc.total?acc.rate+'%':'—')}</div><div class="card">${measure('Cartões revisados',`${cardsReviewed}/40`)}</div><div class="card">${measure('Laboratórios concluídos',`${progress.labChallenges.length}/5`)}</div><div class="card">${measure('XP acumulado',progress.xp)}</div><div class="card">${measure('Nível atual',level())}</div></div><div class="section-head"><h2>Desempenho por assunto</h2></div><div class="grid g2">${modules.map(m=>{const a=accuracy(m.id);return `<div class="card"><div class="score-row"><span>${esc(m.title)}</span><span>${a.total?a.rate+'%':'Ainda sem dados'}</span></div>${bar(a.rate)}<p class="notice">${a.correct} acertos em ${a.total} tentativas · ${progressM(m)}/${m.lessons.length} aulas</p><a class="link" href="#exercicios/${m.id}">Praticar →</a></div>`}).join('')}</div><div class="section-head"><h2>Conquistas e recompensas</h2></div><div class="grid g3">${badges.map(b=>`<div class="achievement ${progress.achievements[b.id]?'':'locked'}"><span class="medal">${b.icon}</span><div><h4>${esc(b.title)} ${progress.achievements[b.id]?'✓':'🔒'}</h4><p>${esc(b.desc)}</p>${progress.achievements[b.id]?`<p class="tiny">Conquistado em ${new Date(progress.achievements[b.id]).toLocaleDateString('pt-BR')}</p>`:''}</div></div>`).join('')}</div><div class="section-head"><h2>Minha evolução</h2></div><div class="card">${reviewSummary()}<div class="divider"></div><h3>Gerenciar meus dados</h3><p class="notice">O progresso é salvo no armazenamento local deste navegador. Limpar dados do navegador pode removê-lo; exporte uma cópia para segurança.</p><div class="btn-row"><button class="btn btn-secondary" data-action="export">↓ Exportar JSON</button><label class="btn btn-secondary" for="import-file">↑ Importar JSON</label><input id="import-file" type="file" accept="application/json,.json" hidden><button class="btn btn-danger" data-action="reset-progress">Apagar progresso</button></div></div>`}
function reviewSummary(){const byTopic=modules.map(m=>({m,a:accuracy(m.id)})).filter(x=>x.a.total);if(!byTopic.length)return `<p>Comece a praticar exercícios para receber recomendações personalizadas e observar sua evolução por assunto.</p>`;const weakest=[...byTopic].sort((a,b)=>a.a.rate-b.a.rate)[0];const improve=questions.filter(q=>{const att=progress.attempts.filter(a=>a.id===q.id);return att.some(a=>!a.correct)&&att.some(a=>a.correct)}).length;const trend=byTopic.map(({m,a})=>{const t=progress.attempts.filter(x=>questionById(x.id)?.topic===m.id);if(t.length<10)return '';const first=t.slice(0,5),last=t.slice(-5);return `<p>Em ${esc(m.title)}, você acertou ${percent(first.filter(x=>x.correct).length,5)}% nas primeiras 5 tentativas e ${percent(last.filter(x=>x.correct).length,5)}% nas 5 mais recentes.</p>`}).filter(Boolean).join('');return `<p>Você realizou <strong>${progress.attempts.length}</strong> tentativas em ${doneSet().size} exercícios acertados ao menos uma vez.</p><p>${improve?`Você já transformou <strong>${improve}</strong> erros em acertos posteriormente. Continue revisando!`:'Os erros podem ser revistos até você acertar; suas correções aparecerão aqui.'}</p><p><strong>Conteúdo que merece atenção:</strong> ${esc(weakest.m.title)} (${weakest.a.rate}% de acertos em ${weakest.a.total} tentativas).</p>${trend}${button('Reforçar este conteúdo',`#exercicios/${weakest.m.id}`,false)}`}
const formulaMap=[['Autoionização','2 H₂O ⇌ H₃O⁺ + OH⁻; Kw≈[H₃O⁺][OH⁻]'],['pH e pOH','pH≈−log[H₃O⁺]; pOH≈−log[OH⁻]; pH+pOH≈14 (25 °C)'],['Indicadores','HIn ⇌ H⁺ + In⁻; cor varia com a razão entre formas'],['Tampões','pH≈pKa+log([A⁻]/[HA])'],['Hidrólise','Ka(conjugado)×Kb(conjugado)≈Kw; [H₃O⁺]≈√(Ka·C) em condições restritas'],['Kps','AgCl: Kps≈[Ag⁺][Cl⁻]; CaF₂: Kps≈[Ca²⁺][F⁻]²']];
function intensive(){return `<div class="page-intro"><span class="kicker">REVISÃO PARA A PROVA</span><h1>Intensivão de Química</h1><p>Um roteiro de 35 minutos é uma sugestão, não um cronômetro. Revise conceitos essenciais e resolva um simulado final no seu ritmo.</p></div><div class="grid g2"><div class="card"><h3>Plano de revisão rápida · ~35 min</h3><div class="study-plan">${[['5 min','Revise íons, ácidos/bases e potências.','#aprender/fundamentos'],['10 min','Passe pelas cinco sínteses temáticas.','#aprender'],['5 min','Estude o mapa das fórmulas.','#intensivao'],['5 min','Relembre erros conceituais comuns.','#intensivao'],['10 min','Faça o desafio de 10 questões.','#exercicios']].map(([t,d,h])=>`<div class="study-step"><span class="tag">${t}</span><div><strong>${d}</strong><a class="link" href="${h}">Abrir →</a></div></div>`).join('')}</div></div><div class="card"><h3>Revisão aprofundada</h3><p>Use um ciclo por conteúdo: explique em voz alta, resolva um exemplo, altere o laboratório e responda questões, consultando a explicação apenas depois de tentar.</p><div class="pill-list">${modules.map(m=>`<a class="pill" href="#aprender/${m.id}">${m.emoji} ${esc(m.title)}</a>`).join('')}</div></div></div><div class="section-head"><h2>Mapa de fórmulas comentado</h2></div><div class="grid g2">${formulaMap.map(([name,formula])=>`<div class="card"><h3>${name}</h3><div class="formula" style="font-size:17px">${esc(formula)}</div><p class="notice">${name==='Tampões'?'Use apenas quando as duas espécies do par fraco/conjugado estiverem presentes e as aproximações forem válidas.':name==='Kps'?'Os expoentes seguem os coeficientes estequiométricos; não inclua sólido puro.':name==='Hidrólise'?'A raiz é aproximação para hidrólise pequena e solução não extremamente diluída.':name==='pH e pOH'?'A soma 14 depende de 25 °C e de modelos diluídos.':'Interprete cada espécie e a condição do equilíbrio antes de calcular.'}</p></div>`).join('')}</div><div class="section-head"><h2>Erros comuns a evitar</h2></div><div class="grid g2">${[['pH 7 não é sempre neutro','Neutralidade significa [H₃O⁺]=[OH⁻], e o pH depende de T.'],['Indicador não mede pH exato','A mudança de cor representa uma faixa de viragem.'],['Tampão não é blindagem infinita','O par ácido/base conjugada pode ser consumido.'],['Sal não é necessariamente neutro','Alguns de seus íons hidrolisam e alteram pH.'],['Expoentes do Kps importam','CaF₂ gera [F⁻]² no Kps, não [F⁻].'],['Q não é sempre Kps','Q é situação atual; só no equilíbrio de saturação vale Q≈Kps.']].map(([title,copy])=>`<div class="card"><h3>✕ ${title}</h3><p class="muted">${copy}</p></div>`).join('')}</div><div class="section-head"><h2>Simulado final</h2></div><div class="card"><h3>Escolha o tamanho do desafio</h3><p class="muted">Receba feedback imediato durante o simulado e um balanço das respostas ao terminar.</p><div class="btn-row">${[10,20,30].map(size=>`<button class="btn btn-primary" data-action="start-sim" data-size="${size}">${size} questões →</button>`).join('')}</div></div>`}
function resultPage(){const result=progress.simulations.at(-1);if(!result)return `<div class="page-intro"><h1>Nenhum simulado concluído ainda</h1><p>Escolha 10, 20 ou 30 questões no Intensivão.</p></div>${button('Iniciar revisão','#intensivao')}`;const rate=percent(result.correct,result.total);const details=Object.entries(result.byTopic||{}).map(([id,v])=>`<div class="card"><div class="score-row"><span>${esc(nameById(id))}</span><span>${v.correct}/${v.total} acertos</span></div>${bar(percent(v.correct,v.total))}<a href="#aprender/${id}" class="link">Revisar o tema →</a></div>`).join('');return `<div class="page-intro"><span class="kicker">RESULTADO DO SIMULADO</span><h1>Você está evoluindo.</h1><p>Seu resultado foi registrado com base nas respostas verificadas.</p></div><div class="grid g3"><div class="card">${measure('Questões corretas',`${result.correct}/${result.total}`)}</div><div class="card">${measure('Taxa de acerto',rate+'%')}</div><div class="card">${measure('Sem resposta',result.unanswered||0)}</div></div><div class="section-head"><h2>Resultado por assunto</h2></div><div class="grid g2">${details}</div><div class="card" style="margin-top:20px"><h3>Seu próximo passo</h3><p>Priorize os assuntos com menor taxa de acerto e refaça questões erradas. Leia a justificativa antes de tentar outra vez.</p><div class="btn-row">${button('Revisar meus erros','#exercicios',false)}${button('Voltar ao Intensivão','#intensivao')}</div></div>`}
function references(){const refs=[['Mundo Educação — Equilíbrio iônico da água','https://mundoeducacao.uol.com.br/quimica/equilibrio-ionico-agua.htm'],['Professor Carlos Junior — Equilíbrio iônico','https://professorcarlosjunior.com.br/equilibrio-ionico/'],['Brasil Escola — Equilíbrio iônico da água','https://brasilescola.uol.com.br/quimica/equilibrio-ionico-agua.htm'],['Cola da Web — pH e pOH','https://www.coladaweb.com/quimica/fisico-quimica/ph-e-poh-equilibrio-ionico-da-agua'],['Mundo Educação — Indicadores ácido-base','https://mundoeducacao.uol.com.br/quimica/indicadores-acido-base.htm'],['Mundo Educação — Hidrólise salina','https://mundoeducacao.uol.com.br/quimica/hidrolise-salina.htm'],['Mundo Educação — Produto de solubilidade','https://mundoeducacao.uol.com.br/quimica/produto-solubilidade.htm'],['Khan Academy — Soluções tampão','https://pt.khanacademy.org/science/chemistry/acid-base-equilibrium/acid-base-equilibrium/buffer-solutions/v/buffer-system'],['Unicamp/Chemkeys — Soluções tampão','https://econtents.sbu.unicamp.br/inpec/index.php/chemkeys/article/view/13548']];return `<div class="page-intro"><span class="kicker">FONTES E TRANSPARÊNCIA</span><h1>Ciência com contexto.</h1><p>Explicações originais, bibliografia para aprofundamento e simplificações identificadas sempre que os modelos químicos não são exatos.</p></div><div class="card"><h2>Referências para estudar</h2><ul class="ref-list">${refs.map(([name,url])=>`<li><a target="_blank" rel="noopener noreferrer" href="${esc(url)}">${esc(name)} ↗</a></li>`).join('')}</ul><div class="divider"></div><h3>Notas de metodologia</h3><p>Os cálculos didáticos usam concentrações no lugar de atividades e assumem, conforme cada laboratório, soluções suficientemente diluídas e temperatura determinada. As constantes de exemplo são valores aproximados; efeitos cinéticos, força iônica e formação de complexos não estão incluídos.</p><p>As animações e gráficos ajudam a interpretar modelos e não correspondem a uma medição experimental real.</p><p>O conteúdo foi escrito para estudantes de Ensino Médio, não como orientação para misturar reagentes de laboratório em casa.</p></div>`}
function diagnostic(){return `<div class="page-intro"><span class="kicker">OPCIONAL · SEM BLOQUEIOS</span><h1>Vamos descobrir seu ponto de partida?</h1><p>Um diagnóstico de cinco questões ajuda a sugerir revisões. Nada será bloqueado por sua nota.</p></div><div class="card center"><h2>Pronto para testar seus conhecimentos?</h2><p>As perguntas são retiradas do banco real da plataforma e possuem comentários explicativos.</p><button class="btn btn-primary" data-action="start-diagnostic">Começar diagnóstico →</button>${progress.diagnostic?`<p class="notice">Último diagnóstico: ${progress.diagnostic.correct}/${progress.diagnostic.total} acertos. ${progress.diagnostic.correct<=2?'Sugerimos começar pelos fundamentos.':'Você pode explorar diretamente os módulos principais.'}</p>`:''}</div>`}
function render(){refreshBadges();updateHeader();const hash=decodeURIComponent(location.hash.replace(/^#/,'')||'inicio'),[route,a,b]=hash.split('/');let html;switch(route){case 'inicio':html=home();break;case 'aprender':html=a?moduleIndex(a):learn();break;case 'aula':html=lesson(a,b||0);break;case 'laboratorio':html=labPage(a);break;case 'cartoes':html=cardsPage();break;case 'exercicios':if(a&&byId(a)){practice.topic=a;practice.index=0;practice.selected=null;practice.feedback=null;practice.order=null;practice.mode='livre';}html=questionPage();break;case 'progresso':html=statsView();break;case 'intensivao':html=intensive();break;case 'resultado':html=resultPage();break;case 'diagnostico':html=diagnostic();break;case 'referencias':html=references();break;default:html=home()}main.innerHTML=html;setNavigation(route==='aula'?'aprender':['intensivao','diagnostico'].includes(route)?'exercicios':route);$('#sidebar').classList.remove('open');$('#menu-btn').setAttribute('aria-expanded','false');if(route==='laboratorio')updateLab();window.scrollTo({top:0,behavior:'instant'})}
function normalize(s){return String(s).toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ')}
function checkQuestion(q){if(q.type==='numeric'){const s=$('#number-answer')?.value.trim().replace(',','.');if(!s)return null;const v=Number(s);if(!Number.isFinite(v))return null;return Math.abs(v-q.correct)<=q.tolerance}
if(q.type==='fill'){const s=$('#fill-answer')?.value;if(!s?.trim())return null;return q.answers.some(a=>normalize(a)===normalize(s))}
if(q.type==='match'){const arr=[...main.querySelectorAll('.match-input')];if(!arr.length||arr.some(e=>!e.value))return null;return arr.every((el,i)=>el.value===q.pairs[i][1])}
if(practice.selected===null)return null;return practice.selected===q.correct}
function verifyQuestion(){const arr=filteredQuestions(),q=arr[practice.index];if(!q)return;const correct=checkQuestion(q);if(correct===null){toast('Escolha ou digite sua resposta primeiro.');return}progress.attempts.push({id:q.id,correct,when:uid(),mode:practice.mode});practice.feedback={correct};practice.answers[q.id]=correct;save();if(correct)awardUpdate('question-'+q.id,10);else updateHeader();renderQuestionKeepFocus()}
function renderQuestionKeepFocus(){const y=window.scrollY;main.innerHTML=questionPage();window.scrollTo({top:y,behavior:'instant'})}
function chooseMode(mode){practice={...practice,mode,index:0,selected:null,feedback:null,answers:{},hint:false,order:null,sessionId:uid()};renderQuestionKeepFocus()}
function completeSimulation(){const fromSim=practice.mode==='simulado';const arr=filteredQuestions();if(practice.mode==='simulado'){const answered=arr.filter(q=>q.id in practice.answers),correct=answered.filter(q=>practice.answers[q.id]).length;const byTopic={};for(const q of arr){const item=byTopic[q.topic]||(byTopic[q.topic]={total:0,correct:0});item.total++;if(practice.answers[q.id])item.correct++}progress.simulations.push({at:uid(),total:arr.length,correct,unanswered:arr.length-answered.length,byTopic,finished:answered.length===arr.length});save();refreshBadges();toast(`Simulado: ${correct}/${arr.length} acertos. ${arr.length-answered.length} sem resposta.`)}if(practice.mode==='diagnostico'){const answered=arr.filter(q=>q.id in practice.answers),correct=answered.filter(q=>practice.answers[q.id]).length;progress.diagnostic={correct,total:arr.length,when:uid()};save();toast('Diagnóstico finalizado; veja sua recomendação na página inicial.')}practice={...practice,mode:'livre',order:null,index:0,answers:{},feedback:null,selected:null};go(fromSim?'#resultado':'#diagnostico')}
function rateCard(rating){const card=getDeck()[deck.index];if(!card)return;const old=progress.cards[card.id]||{reviews:0,streak:0};const streak=rating==='ok'?old.streak+1:0;const delta=rating==='ok'?(streak===1?1:streak===2?3:7):rating==='doubt'?1:0;const d=new Date();d.setDate(d.getDate()+delta);progress.cards[card.id]={reviews:old.reviews+1,streak,nextDue:d.toISOString().slice(0,10),lastRating:rating,lastReview:uid()};save();awardUpdate(`flash-${card.id}-${today()}`,2);deck.flipped=false;const total=getDeck().length;deck.index=total?Math.min(deck.index+1,total-1):0;render()}
function handleClick(e){const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;switch(action){case 'lesson-done':{const key=el.dataset.id+'/'+el.dataset.index;if(!progress.completedLessons.includes(key)){progress.completedLessons.push(key);save();awardUpdate('lesson-'+key,20)}render();break}
case 'card-flip':deck.flipped=!deck.flipped;render();break;case 'card-prev':deck.index=Math.max(0,deck.index-1);deck.flipped=false;render();break;case 'card-next':deck.index=Math.min(getDeck().length-1,deck.index+1);deck.flipped=false;render();break;case 'card-rate':rateCard(el.dataset.rating);break;case 'card-shuffle':{const a=getDeck().map(c=>c.id);for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}deck.order=a;deck.index=0;deck.flipped=false;render();break}case 'card-all':deck.onlyDue=false;deck.topic='all';deck.index=0;render();break;
case 'q-choice':practice.selected=Number(el.dataset.choice);main.querySelectorAll('.choice').forEach(c=>c.classList.toggle('selected',c===el));break;case 'q-verify':verifyQuestion();break;case 'q-hint':practice.hint=!practice.hint;renderQuestionKeepFocus();break;case 'q-prev':practice.index=Math.max(0,practice.index-1);practice.selected=null;practice.feedback=null;practice.hint=false;renderQuestionKeepFocus();break;case 'q-next':{const arr=filteredQuestions();if(practice.index>=arr.length-1){if(['diagnostico','simulado'].includes(practice.mode))completeSimulation();else {practice.index=0;renderQuestionKeepFocus()}}else{practice.index++;practice.selected=null;practice.feedback=null;practice.hint=false;renderQuestionKeepFocus()}break}
case 'q-reset-filters':practice={...practice,topic:'all',level:'all',mode:'livre',order:null,index:0,selected:null,feedback:null};renderQuestionKeepFocus();break;
case 'lab-reset':{main.innerHTML=labPage(labId);updateLab();break}case 'lab-challenge':{const won=checkLabChallenge();$('#lab-challenge-msg').textContent=won?'✓ Desafio concluído! Parabéns.':'Ainda não! Releia o objetivo e ajuste os controles.';if(won&&!progress.labChallenges.includes(labId)){progress.labChallenges.push(labId);save();awardUpdate('lab-'+labId,35)}break}
case 'start-sim':practice={topic:'all',level:'all',mode:'simulado',size:+el.dataset.size,order:null,index:0,selected:null,feedback:null,answers:{},hint:false,sessionId:uid()};go('#exercicios');break;
case 'start-diagnostic':practice={topic:'fundamentos',level:'all',mode:'diagnostico',size:5,order:null,index:0,selected:null,feedback:null,answers:{},hint:false,sessionId:uid()};go('#exercicios');break;
case 'export':{const blob=new Blob([JSON.stringify(progress,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='equilibra-progresso.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);break}
case 'reset-progress':if(window.confirm('Deseja apagar TODO o progresso deste navegador? Esta ação não pode ser desfeita sem uma cópia exportada.')){reset();deck={topic:'all',onlyDue:false,index:0,flipped:false,order:null};practice={topic:'all',level:'all',mode:'livre',size:10,order:null,index:0,selected:null,feedback:null,answers:{},hint:false};render();toast('Seu progresso foi reiniciado.')}break}}
function handleChange(e){const id=e.target.id;switch(id){case 'card-topic':deck.topic=e.target.value;deck.index=0;deck.order=null;deck.flipped=false;render();break;case 'due-only':deck.onlyDue=e.target.checked;deck.index=0;deck.order=null;deck.flipped=false;render();break;case 'q-mode':chooseMode(e.target.value);break;case 'q-topic':practice.topic=e.target.value;practice.index=0;practice.order=null;practice.answers={};practice.selected=null;practice.feedback=null;renderQuestionKeepFocus();break;case 'q-level':practice.level=e.target.value;practice.index=0;practice.order=null;practice.answers={};practice.selected=null;practice.feedback=null;renderQuestionKeepFocus();break;case 'q-size':practice.size=+e.target.value;practice.index=0;practice.order=null;practice.answers={};renderQuestionKeepFocus();break;
case 'lab-sample':{const s=samples[e.target.value];if(s){$('#lab-ph').value=s.ph;updateLab()}break}
case 'import-file':{const f=e.target.files?.[0];if(!f)return;f.text().then(t=>{if(!window.confirm('Importar progresso substituirá os dados atuais. Continuar?'))return;try{replace(JSON.parse(t));refreshBadges();render();toast('Progresso importado com sucesso.')}catch(err){toast(err.message)}}).catch(()=>toast('Não foi possível ler o arquivo.'));break}}
if(e.target.classList.contains('lab-input'))updateLab()}
function updateLab(){if(!$('#lab-out'))return;if($('#ph-label'))$('#ph-label').textContent=fmt(+( $('#lab-ph')?.value||7),1);if($('#add-label'))$('#add-label').textContent=fmt(+( $('#lab-add')?.value||0),3);$('#lab-out').innerHTML=labResult(labId)}
main.addEventListener('click',handleClick);main.addEventListener('change',handleChange);main.addEventListener('input',e=>{if(e.target.classList.contains('lab-input'))updateLab()});
$('#theme-btn').addEventListener('click',()=>{progress.theme=progress.theme==='dark'?'light':'dark';save();updateHeader()});
$('#menu-btn').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-btn').setAttribute('aria-expanded',String(open))});
window.addEventListener('hashchange',()=>{const [route]=location.hash.slice(1).split('/');if(route!=='exercicios'&&['simulado','diagnostico'].includes(practice.mode)){}render()});
render();
